        "test_accuracy": {
          "file": "paper/main.tex",
          "anchor": {
            "exact": "86.0\\%"
          },
          "metric": "test_accuracy"
        }
      },
      "metrics": {
        "test_accuracy": {
          "source": "results/metrics.csv",
          "field": "accuracy",
          "unit": "percent",
          "reduce": "mean",
          "where": {
            "dataset": "Data-A",
            "model": "Ours",
            "split": "test"
          }
        }
      }
    },
    "rationale": {
      "test_accuracy": "The test accuracy is explicitly stated as 86.0% on Data-A in the manuscript, and the results/metrics.csv file contains three entries for the same dataset, model, and split with seeds 1, 2, and 3, which correspond to the requested run set. The metric 'accuracy' in the CSV file is consistent with the value reported in the manuscript, and the units are specified as a percentage."
    }
  }
}
